import styled from "styled-components";

export const LandImageContainer=styled.div`
    width: 100%;
    height: 100%;
`
export const LandImageItemContainer=styled.div`
    width: 100%;
    height: 100%;
    display: flex;
    
`

export const LandImageContainerVW=styled.div`
    width: 85%;
    height: 100%;

    img{
        width:100%;
        height:100%;
        object-fit: cover;
        border-radius: 5px;
    }
`
export const LandImageContainerVH=styled.div`
    width: 15%;
    height: 100%;
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: space-between;
    padding:5px;

    div{
        display: flex;
        align-items: center;
        flex-direction: column;
        justify-content: space- between;
        width:70%;
        height:80%;
        object-fit: cover;
        
    }
    img{
        width:100%;
        height:100%;
        object-fit: cover;
        border-radius: 5px;
        
    }

`
